buildCommand:
printf 'const FIREBASE_CONFIG = {
  apiKey: "%s",
  authDomain: "%s",
  projectId: "%s",
  storageBucket: "%s",
  messagingSenderId: "%s",
  appId: "%s"
};
' "$FIREBASE_API_KEY" "$FIREBASE_AUTH_DOMAIN" "$FIREBASE_PROJECT_ID" "$FIREBASE_STORAGE_BUCKET" "$FIREBASE_MESSAGING_SENDER_ID" "$FIREBASE_APP_ID" > config.js && rm -f firestore.rules firebase.json config.example.js README.md CLAUDE.md && rm -rf functions/
